        } else if (op == '*') {
            result *= num;
        }
    }
    return result;
}

// Evaluate expression with multiplication first precedence
int evalMultiplicationFirst(const string& expr) {
    vector<int> numbers;
    vector<char> ops;
    stringstream ss(expr);
    int num;
    char op;

    // Parse first number
    ss >> num;
    numbers.push_back(num);

    while (ss >> op >> num) {
        ops.push_back(op);
        numbers.push_back(num);
    }

    // First pass: handle all multiplications
    vector<int> finalNumbers;
    vector<char> finalOps;

    finalNumbers.push_back(numbers[0]);

    for (size_t i = 0; i < ops.size(); i++) {
        if (ops[i] == '*') {
            // Multiply with last number in finalNumbers
            finalNumbers.back() *= numbers[i + 1];
        } else {
            finalNumbers.push_back(numbers[i + 1]);
            finalOps.push_back('+');
        }
    }

    // Second pass: handle additions
    int result = finalNumbers[0];
    for (size_t i = 0; i < finalOps.size(); i++) {
        result += finalNumbers[i + 1];
    }

    return result;
}

