def eval_precedence(expr: str) -> int:
    # Normal arithmetic: multiplication before addition
    terms = expr.split('+')
    total = 0
    for term in terms:
        prod = 1
        for x in term.split('*'):
            prod *= int(x)
        total += prod
    return total

def eval_left_to_right(expr: str) -> int:
    # Evaluate strictly from left to right
    cur = int(expr[0])
    i = 1
    while i < len(expr):
        op = expr[i]
        val = int(expr[i + 1])
        if op == '+':
            cur += val
        else:
            cur *= val
        i += 2
    return cur

