    private static long evaluateLeftToRight(String expr) {
        // expression is like "2+3*4"
        long result = 0;
        char lastOp = '+';
        int i = 0;
        while (i < expr.length()) {
            char c = expr.charAt(i);
            if (Character.isDigit(c)) {
                long num = c - '0';
                if (lastOp == '+') {
                    result += num;
                } else { // '*'
                    result *= num;
                }
            } else if (c == '+' || c == '*') {
                lastOp = c;
            }
            i++;
        }
        return result;
    }

    private static long evaluateMultiplicationFirst(String expr) {
        // First, parse all numbers and operators
        List<Long> numbers = new ArrayList<>();
        List<Character> ops = new ArrayList<>();
        for (int i = 0; i < expr.length(); i++) {
            char c = expr.charAt(i);
            if (Character.isDigit(c)) {
                numbers.add((long)(c - '0'));
            } else if (c == '+' || c == '*') {
                ops.add(c);
            }
        }
        // Process multiplication first
        // We'll combine numbers that are multiplied
        List<Long> finalNumbers = new ArrayList<>();
        finalNumbers.add(numbers.get(0));
        for (int i = 0; i < ops.size(); i++) {
            if (ops.get(i) == '*') {
                long last = finalNumbers.remove(finalNumbers.size() - 1);
                finalNumbers.add(last * numbers.get(i + 1));
            } else {
                finalNumbers.add(numbers.get(i + 1));
            }
        }
        // Now sum the rest
        long sum = 0;
        for (long num : finalNumbers) {
            sum += num;
        }
        return sum;
    }
}

